import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Pasted, ViewMode } from '../types'

const PANE = 'img-viewer'
const files = atom({ plugin: 'img-viewer', key: 'files' } as const, [] as string[])
const index = atom({ plugin: 'img-viewer', key: 'index' } as const, 0)
const mode = atom({ plugin: 'img-viewer', key: 'mode' } as const, 'block' as ViewMode)
const pasted = atom({ plugin: 'img-viewer', key: 'pasted' } as const, [] as Pasted[])
const IMAGE_TAG = /\[Image #(\d+)\]/g

export const EXTENSIONS = ['png', 'jpg', 'jpeg', 'gif', 'bmp', 'tif', 'tiff', 'ico', 'webp']
const DEFAULT_COLOR = 0x01000000

/**
 * Quadrant glyphs by which of a cell's four pixels take the foreground:
 * bit 1 top-left, 2 top-right, 4 bottom-left, 8 bottom-right.
 */
const QUADRANT = [
  0x20, 0x2598, 0x259d, 0x2580, 0x2596, 0x258c, 0x259e, 0x259b,
  0x2597, 0x259a, 0x2590, 0x259c, 0x2584, 0x2599, 0x259f, 0x2588,
]

/** One decode: the picture fitted to a box of cells, packed as Raster cells. */
type Frame =
  | {
      kind: 'ok'
      /** Cells across and down. */
      columns: number
      rows: number
      srcWidth: number
      srcHeight: number
      cells: string
      png?: string
    }
  | { kind: 'error'; message: string }

// Module-level cache: a reload empties it, which only costs a re-decode.
const frames = new Map<string, Frame>()
const pending = new Set<string>()

export const isImage = (name: string) => {
  const dot = name.lastIndexOf('.')
  return dot > 0 && EXTENSIONS.includes(name.slice(dot + 1).toLowerCase())
}
const baseName = (path: string) =>
  path.slice(Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\')) + 1)
const dirName = (path: string) => {
  const cut = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'))
  if (cut < 0) return '.'
  // Keep a drive or filesystem root a root: "C:\" and "/".
  return cut === 0 || /^[A-Za-z]:$/.test(path.slice(0, cut)) ? path.slice(0, cut + 1) : path.slice(0, cut)
}
const isWindowsPath = (path: string) => /^[A-Za-z]:[\\/]/.test(path)
const join = (dir: string, name: string) => {
  const sep = isWindowsPath(dir) ? '\\' : '/'
  return /[\\/]$/.test(dir) ? `${dir}${name}` : `${dir}${sep}${name}`
}
const unquote = (text: string) => text.trim().replace(/^(["'])(.*)\1$/, '$2')
const firstLine = (text: string) => text.trim().split(/\r?\n/)[0] ?? ''
const hash = (text: string) => {
  let h = 2166136261
  for (let i = 0; i < text.length; i++) h = Math.imul(h ^ text.charCodeAt(i), 16777619)
  return (h >>> 0).toString(36)
}

/**
 * Packs a `2 * columns` x `2 * rows` picture into Raster cells, four pixels a
 * cell: each cell splits its pixels into the two color groups that fit them
 * best and draws the quadrant glyph of that split.
 */
export const toCells = (
  px: Uint8Array,
  columns: number,
  rows: number,
  stride: number,
  isBgra: boolean,
) => {
  const words = new Uint32Array(columns * rows * 3)
  const r = [0, 0, 0, 0]
  const g = [0, 0, 0, 0]
  const b = [0, 0, 0, 0]
  for (let cy = 0; cy < rows; cy++) {
    for (let cx = 0; cx < columns; cx++) {
      let opaque = 0
      for (let q = 0; q < 4; q++) {
        const at = (cy * 2 + (q >> 1)) * stride + (cx * 2 + (q & 1)) * 4
        const a = px[at + 3] ?? 0
        if (a >= 128) opaque++
        // Transparent pixels count as black: pastes are almost always opaque.
        const k = a >= 128 ? 1 : 0
        r[q] = ((isBgra ? px[at + 2] : px[at]) ?? 0) * k
        g[q] = (px[at + 1] ?? 0) * k
        b[q] = ((isBgra ? px[at] : px[at + 2]) ?? 0) * k
      }
      const i = (cy * columns + cx) * 3
      if (opaque === 0) {
        words[i] = 0x20
        words[i + 1] = DEFAULT_COLOR
        words[i + 2] = DEFAULT_COLOR
        continue
      }
      // Try each split (masks holding the top-left pixel cover them all once).
      let best = 15
      let bestErr = Infinity
      let bestFg = 0
      let bestBg = 0
      for (let mask = 1; mask < 16; mask += 2) {
        let fr = 0, fg = 0, fb = 0, fn = 0, br = 0, bg = 0, bb = 0, bn = 0
        for (let q = 0; q < 4; q++) {
          if (mask & (1 << q)) { fr += r[q]!; fg += g[q]!; fb += b[q]!; fn++ }
          else { br += r[q]!; bg += g[q]!; bb += b[q]!; bn++ }
        }
        fr /= fn; fg /= fn; fb /= fn
        if (bn) { br /= bn; bg /= bn; bb /= bn }
        let err = 0
        for (let q = 0; q < 4; q++) {
          const isFg = mask & (1 << q)
          const dr = r[q]! - (isFg ? fr : br)
          const dg = g[q]! - (isFg ? fg : bg)
          const db = b[q]! - (isFg ? fb : bb)
          err += dr * dr * 0.3 + dg * dg * 0.59 + db * db * 0.11
        }
        if (err < bestErr) {
          bestErr = err
          best = mask
          bestFg = (Math.round(fr) << 16) | (Math.round(fg) << 8) | Math.round(fb)
          bestBg = bn ? (Math.round(br) << 16) | (Math.round(bg) << 8) | Math.round(bb) : bestFg
        }
        if (err === 0) break
      }
      words[i] = QUADRANT[best]!
      words[i + 1] = bestFg >>> 0
      words[i + 2] = bestBg >>> 0
    }
  }
  return new Uint8Array(words.buffer).toBase64()
}

/** Decodes `path` for a box of `maxCols` x `maxRows` cells: PowerShell on Windows, ImageMagick elsewhere. */
const decode = async (
  $: EngineInterface,
  path: string,
  maxCols: number,
  maxRows: number,
  wantPng: boolean,
): Promise<Frame> => {
  const root = $.plugin.root
  const isPng = path.toLowerCase().endsWith('.png')
  const pngOut = wantPng && !isPng ? join(join(root, '.cache'), `${hash(path)}.png`) : ''
  const png = wantPng ? pngOut || path : undefined

  if (isWindowsPath(root)) {
    const argv = [
      'powershell.exe', '-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass',
      '-File', join(join(root, 'hooks'), 'decode.ps1'),
      '-Path', path, '-MaxCols', String(maxCols), '-MaxRows', String(maxRows),
      ...(pngOut ? ['-OutPng', pngOut] : []),
    ]
    const run = await $.process.run(argv, { timeoutMs: 30_000 })
    if (run.exitCode !== 0) {
      return { kind: 'error', message: firstLine(run.stderr) || `decoder exited ${run.exitCode}` }
    }
    const [head = '', body = ''] = run.stdout.trim().split(/\r?\n/)
    const [w = 0, h = 0, stride = 0, sw = 0, sh = 0] = head.trim().split(' ').map(Number)
    if (!w || !h || !stride) return { kind: 'error', message: `unexpected decoder output: ${head}` }
    const columns = w / 2
    const rows = h / 2
    const cells = toCells(Uint8Array.fromBase64(body.trim()), columns, rows, stride, true)
    return { kind: 'ok', columns, rows, srcWidth: sw, srcHeight: sh, cells, png }
  }

  // POSIX: ImageMagick, raw RGBA through a temp file.
  const info = await $.process.run(['magick', 'identify', '-format', '%w %h\n', `${path}[0]`])
  if (info.exitCode !== 0) {
    return { kind: 'error', message: firstLine(info.stderr) || 'ImageMagick (magick) is required' }
  }
  const [sw = 0, sh = 0] = firstLine(info.stdout).split(/\s+/).map(Number)
  if (!sw || !sh) return { kind: 'error', message: `unexpected identify output: ${info.stdout}` }
  // Cells are about twice as tall as wide: cols / rows = 2 * W / H keeps the shape.
  const fit = Math.min(maxCols, (2 * maxRows * sw) / sh)
  const columns = Math.max(1, Math.round(fit))
  const rows = Math.max(1, Math.min(maxRows, Math.round((fit * sh) / (2 * sw))))
  const raw = `/tmp/img-viewer-${hash(path)}-${columns}x${rows}.rgba`
  const conv = await $.process.run([
    'magick', `${path}[0]`, '-resize', `${columns * 2}x${rows * 2}!`, '-depth', '8', `rgba:${raw}`,
  ])
  if (conv.exitCode !== 0) return { kind: 'error', message: firstLine(conv.stderr) }
  if (pngOut) {
    await $.fs.write(join(join(root, '.cache'), '.keep'), '')
    await $.process.run(['magick', `${path}[0]`, pngOut])
  }
  const { base64 } = await $.fs.read(raw, { as: 'bytes' })
  const cells = toCells(Uint8Array.fromBase64(base64), columns, rows, columns * 8, false)
  return { kind: 'ok', columns, rows, srcWidth: sw, srcHeight: sh, cells, png }
}

/** The cached frame, or undefined after starting its decode; the sites redraw when it lands. */
const ensure = ($: EngineInterface, path: string, maxCols: number, maxRows: number, wantPng: boolean) => {
  const key = `${path}|${maxCols}|${maxRows}|${wantPng}`
  const cached = frames.get(key)
  if (cached || pending.has(key)) return cached
  pending.add(key)
  void decode($, path, maxCols, maxRows, wantPng)
    .catch((error: unknown): Frame => ({
      kind: 'error',
      message: error instanceof Error ? error.message : String(error),
    }))
    .then(frame => {
      frames.set(key, frame)
      if (frames.size > 40) {
        const oldest = frames.keys().next().value
        if (oldest !== undefined) frames.delete(oldest)
      }
      pending.delete(key)
      $.ui.invalidate('ui.render')
    })
  return undefined
}


/** The image files beside `target` (a file) or inside it (a folder), and which to show. */
const collect = async ($: EngineInterface, target: string) => {
  const stat = await $.fs.stat(target, { resolve: true })
  const real = stat.realPath ?? target
  const isDir = stat.kind === 'dir'
  const dir = isDir ? real : dirName(real)
  const entries = await $.fs.list(dir)
  const list = entries
    .filter(one => one.kind === 'file' && isImage(one.name))
    .map(one => one.name)
    .sort((a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' }))
    .map(name => join(dir, name))
  if (!isDir && !list.includes(real)) list.unshift(real)
  return { list, at: isDir ? 0 : Math.max(0, list.indexOf(real)) }
}

const step = async ($: EngineInterface, by: number) => {
  const count = (await read($, files)).length
  await update($, index, i => (count ? ((((i ?? 0) + by) % count) + count) % count : 0))
}
const toggleMode = ($: EngineInterface) =>
  update($, mode, m => (m === 'pixel' ? 'block' : 'pixel'))

/** Terminals that draw kitty graphics, as `TERM_PROGRAM` names them. */
const PIXEL_TERMINALS = ['wezterm', 'kitty', 'ghostty']

/** The host terminal's `TERM_PROGRAM`, or '' when it sets none. */
const terminalProgram = async ($: EngineInterface) => {
  const argv = isWindowsPath($.plugin.root)
    ? ['cmd.exe', '/d', '/c', 'echo %TERM_PROGRAM%']
    : ['sh', '-c', 'echo "$TERM_PROGRAM"']
  const run = await $.process.run(argv).catch(() => undefined)
  const said = firstLine(run?.stdout ?? '')
  return said === '%TERM_PROGRAM%' ? '' : said
}

/** Opens the viewer as a dialog: it takes the keys and Esc closes it. */
const openModal = ($: EngineInterface) =>
  $.ui.open({ id: PANE, title: 'Image', focus: true, closeOnEscape: true, holdToasts: true })

/**
 * Shows `list[at]` at full quality in a window of its own: a borderless,
 * always-on-top WinForms window on Windows, the system viewer elsewhere.
 */
const openWindow = async ($: EngineInterface, list: string[], at: number) => {
  const root = $.plugin.root
  const path = list[at]
  if (!path) return
  if (!isWindowsPath(root)) {
    const isMac = (await $.process.run(['uname'])).stdout.trim() === 'Darwin'
    await $.process.run([isMac ? 'open' : 'xdg-open', path])
    return
  }
  const viewer = $.process.spawn({
    argv: [
      'powershell.exe', '-STA', '-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass',
      '-WindowStyle', 'Hidden',
      '-File', join(join(root, 'hooks'), 'viewer.ps1'),
      '-List', list.join('|'), '-Index', String(at),
    ],
  })
  // The loop is the window's life: it ends when the window closes.
  void (async () => {
    for await (const piece of viewer) {
      if (piece.stream === 'stderr') $.ui.log(`img-viewer window: ${piece.text}`, { to: 'debug' })
    }
  })().catch(error =>
    $.ui.log(`img-viewer window: ${error instanceof Error ? error.message : String(error)}`, { to: 'debug' }),
  )
}

let tempDir: string | undefined

/** Looks up the temp folder once; session.start warms it so typing never starts a process. */
const loadTempDir = async ($: EngineInterface) => {
  if (tempDir !== undefined) return
  const isWindows = isWindowsPath($.plugin.root)
  const run = await $.process
    .run(isWindows ? ['cmd.exe', '/d', '/c', 'echo %TEMP%'] : ['sh', '-c', 'echo "${TMPDIR:-/tmp}"'])
    .catch(() => undefined)
  tempDir = firstLine(run?.stdout ?? '').replace(/[\\/]$/, '')
}

/** Where Claude Code keeps this session's `[Image #n]`: <temp>/claude/<project>/<session>/images/<n>.png. */
const sessionImage = async ($: EngineInterface, tag: number) => {
  await loadTempDir($)
  if (!tempDir) return undefined
  const project = (await $.session.cwd()).replace(/[:\\/]/g, '-')
  const dir = [tempDir, 'claude', project, await $.session.id(), 'images'].reduce(join)
  const path = join(dir, `${tag}.png`)
  return (await $.fs.exists(path)) ? path : undefined
}

/** Opens the window on the images a past message carried, at `tag`. */
const openTags = async ($: EngineInterface, tags: number[], tag: number) => {
  const pastedNow = await read($, pasted)
  const found: { tag: number; path: string }[] = []
  for (const one of tags) {
    const path =
      (await sessionImage($, one)) ?? pastedNow.find(p => p.match === `[Image #${one}]`)?.path
    if (path) found.push({ tag: one, path })
  }
  const at = found.findIndex(one => one.tag === tag)
  if (at < 0) {
    $.ui.toast(`Image #${tag} is no longer on disk`)
    return
  }
  await openWindow($, found.map(one => one.path), at)
}

const showPasted = async ($: EngineInterface, at: number) => {
  const list = (await read($, pasted)).map(one => one.path)
  await update($, files, () => list)
  await update($, index, () => at)
  await openWindow($, list, at)
}

const grabbing = new Set<number>()
/** Tags given up on: never on disk, so the draft does not look for them again. */
const grabbed = new Set<number>()

/** Keeps the thumbnails in step with the draft: new `[Image #n]` tags or pasted paths in, removed ones out. */
const syncPasted = async ($: EngineInterface, inputText: string, draft: string) => {
  const added: Pasted[] = []
  const current = await read($, pasted)
  for (const match of draft.matchAll(IMAGE_TAG)) {
    const tag = Number(match[1])
    if (current.some(one => one.match === match[0]) || grabbing.has(tag)) continue
    if (grabbed.has(tag)) continue
    grabbing.add(tag)
    try {
      // Claude Code's own copy first: a file check, no process. The tag shows in
      // the draft before that file is written, so wait for it a few seconds
      // rather than start a PowerShell right as the person goes back to typing.
      let saved: string | undefined
      for (let tries = 0; tries < 10 && !saved; tries++) {
        if (tries > 0) await $.clock.sleep(300)
        saved = await sessionImage($, tag)
      }
      if (saved) {
        added.push({ match: match[0], path: saved, label: `Image #${tag}` })
        continue
      }
      // No clipboard fallback: starting a PowerShell under the terminal while the
      // person types resets the Korean/English IME, so a tag never found is skipped.
      grabbed.add(tag)
      $.ui.log(`img-viewer: Image #${tag} not on disk, skipped`, { to: 'debug' })
    } finally {
      grabbing.delete(tag)
    }
  }
  const typed = unquote(inputText)
  if (typed && !/[\r\n]/.test(typed) && isImage(typed) && !current.some(one => one.match === typed)) {
    const stat = await $.fs.stat(typed, { resolve: true }).catch(() => undefined)
    if (stat?.kind === 'file') added.push({ match: typed, path: stat.realPath ?? typed, label: baseName(typed) })
  }
  const stillThere = (one: Pasted) => draft.includes(one.match)
  if (added.length === 0 && current.every(stillThere)) return
  await update($, pasted, list => [
    ...(list ?? []).filter(stillThere),
    ...added.filter(one => !(list ?? []).some(old => old.match === one.match)),
  ])
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'img',
      description: 'View images in a pane (n/p browse, m block/pixel mode, q close)',
      argumentHint: '[file | folder | next | prev | mode | close]',
    })
    // An image paste raises no prompt.edit: watch the draft so its label shows at once.
    let lastDraft = ''
    let isSyncing = false
    $.clock.every(400, async () => {
      if (isSyncing) return
      const { text } = await $.prompt.read()
      if (text === lastDraft) return
      lastDraft = text
      isSyncing = true
      try {
        await syncPasted($, '', text)
      } finally {
        isSyncing = false
      }
    })
    await loadTempDir($)
    // First load this session: pixels where the terminal draws them, blocks elsewhere.
    const { value } = await $.state.get({ plugin: 'img-viewer', key: 'mode' })
    if (value === undefined) {
      const program = await terminalProgram($)
      if (PIXEL_TERMINALS.some(name => program.toLowerCase().includes(name))) {
        await update($, mode, () => 'pixel')
      }
    }
    return next(e)
  })

  on('prompt.edit', async ($, e, next) => {
    const box = await next(e)
    // Off the editor's path: waiting for the image file takes a moment.
    void syncPasted($, e.inputText, box.text).catch(error =>
      $.ui.log(`img-viewer: ${error instanceof Error ? error.message : String(error)}`, { to: 'debug' }),
    )
    return box
  })

  on('prompt.submit', async ($, e, next) => {
    const sent = await next(e)
    await update($, pasted, () => [])
    return sent
  }).catch(() => undefined) // a failed clear never holds up the prompt

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const list = await read($, pasted)
    if (e.props.hasSurvey || list.length === 0 || e.surface !== 'terminal') return next(e)
    const { Box, Text, Button } = $.ui.resolve(e)

    // No preview: one clickable label per pasted image, opening the full-quality window.
    return (
      <Box flexDirection="row" gap={2}>
        <Text dimColor>Images:</Text>
        {list.map((one, i) => (
          <Button
            key={`open-${i}`}
            plain
            onPress={() => showPasted($, i)}
          >
            {one.label}
          </Button>
        ))}
      </Box>
    )
  })

  // Past prompts that carried images get a clickable label per image under them.
  on('ui.render', { component: 'UserMessage' }, async ($, e, next) => {
    const drawn = await next(e)
    if (e.surface !== 'terminal') return drawn
    const tags = [...new Set([...e.props.text.matchAll(IMAGE_TAG)].map(m => Number(m[1])))]
    if (tags.length === 0) return drawn
    const { Box, Text, Button } = $.ui.resolve(e)
    return (
      <Box flexDirection="column">
        {drawn}
        <Box flexDirection="row" gap={2} paddingLeft={2}>
          <Text dimColor>view:</Text>
          {tags.map(tag => (
            <Button key={`msg-image-${tag}`} plain dimColor onPress={() => openTags($, tags, tag)}>
              {`Image #${tag}`}
            </Button>
          ))}
        </Box>
      </Box>
    )
  })

  on('command.run', { command: 'img' }, async ($, e) => {
    const arg = unquote(e.args)
    if (arg === 'close') {
      await $.ui.close({ id: PANE })
      return { text: 'Image viewer closed.' }
    }
    if (arg === 'next' || arg === 'prev') {
      await step($, arg === 'next' ? 1 : -1)
    } else if (arg === 'mode') {
      await toggleMode($)
    } else {
      const target = arg || '.'
      if (!(await $.fs.exists(target))) return { text: `No such file or folder: ${target}` }
      const { list, at } = await collect($, target)
      if (list.length === 0) return { text: `No images in ${target} (${EXTENSIONS.join(', ')}).` }
      await update($, files, () => list)
      await update($, index, () => at)
    }
    await openModal($)
    const list = await read($, files)
    const i = await read($, index)
    return {
      text: list.length
        ? `Showing ${baseName(list[i] ?? '')} (${i + 1}/${list.length}).`
        : 'No image open.',
    }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    if (e.surface !== 'terminal') {
      const { Text } = $.ui.resolve(e)
      return <Text dimColor>The image viewer draws on the terminal only.</Text>
    }
    const { Box, Text, Button, Raster, Image } = $.ui.resolve(e)
    const list = await read($, files)
    const i = await read($, index)
    const viewMode = await read($, mode)
    const path = list[i]

    const cols = Math.max(4, Math.min(512, e.props.bodyColumns))
    // Two rows for the header and the buttons.
    const rows = Math.max(2, Math.min(255, e.props.scroll.bodyRows - 2))
    const wantPng = viewMode === 'pixel'

    const controls = (
      <Box flexDirection="row" gap={1}>
        <Button key="prev" hotkey="p" onPress={() => step($, -1)}>Prev</Button>
        <Button key="next" hotkey="n" onPress={() => step($, 1)}>Next</Button>
        <Button key="window" hotkey="w" variant="primary" onPress={async () => openWindow($, await read($, files), await read($, index))}>
          Window
        </Button>
        <Button key="mode" hotkey="m" onPress={() => toggleMode($)}>
          {viewMode === 'pixel' ? 'Blocks' : 'Pixels'}
        </Button>
        <Button key="close" hotkey="q" role="dismiss" onPress={() => $.ui.close({ id: PANE })}>Close</Button>
      </Box>
    )

    if (!path) {
      return (
        <Box flexDirection="column">
          <Text dimColor>No image. Run /img path/to/picture.png or /img path/to/folder</Text>
          {controls}
        </Box>
      )
    }

    const frame = ensure($, path, cols, rows, wantPng)
    // Warm the neighbours once this one is in, so n and p feel instant.
    if (frame && list.length > 1) {
      for (const near of [list[(i + 1) % list.length], list[(i - 1 + list.length) % list.length]]) {
        if (near) ensure($, near, cols, rows, wantPng)
      }
    }

    const size = frame?.kind === 'ok' ? `  ${frame.srcWidth}x${frame.srcHeight}` : ''
    const header = (
      <Text wrap="truncate-end">
        <Text bold>{baseName(path)}</Text>
        <Text dimColor>{`  ${i + 1}/${list.length}${size}  ${viewMode}`}</Text>
      </Text>
    )

    let body
    if (!frame) {
      body = <Text dimColor>Decoding...</Text>
    } else if (frame.kind === 'error') {
      body = <Text color="red">Cannot show this image: {frame.message}</Text>
    } else if (wantPng && frame.png) {
      body = (
        <Image
          key="view"
          source={{ file: frame.png, format: 'png' }}
          columns={frame.columns}
          rows={frame.rows}
          alt={`${baseName(path)}: no kitty graphics in this terminal, press m for blocks`}
        />
      )
    } else {
      body = (
        <Raster
          key="view"
          columns={frame.columns}
          rows={frame.rows}
          cells={frame.cells}
        />
      )
    }

    return (
      <Box flexDirection="column">
        {header}
        {body}
        {controls}
      </Box>
    )
  })
}

